  S.seedUsed = P.seed;
  const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
  S.hoff = fr(1);          // hue offset
  S.pha = fr(2) * 6.2831;  // spiral phase
  S.aoff = fr(3) * 6.2831; // angular offset
}

const asp = BW / BH;
const cx = P.x, cy = P.y;
const g = S.g; g.loadPixels(); const px = g.pixels;

// clock-driven continuous motion (never re-phases: pure K.t drift)
const zt = K.t * (0.03 + P.speed * 0.06);              // inward log-radius zoom drift
const rt = K.t * (0.08 + P.speed * 0.06) + S.pha;      // rotation drift
const sec = K.section, inten = K.intensity;

const hb = (P.hue + S.hoff * 60 + sec * 24) % 360;
const tw = 0.15 + P.twist * 1.1;                        // spiral pitch (winds bands into log-spiral)
const Lp = 0.30 + (1 - P.zoom) * 1.45;                  // recursion period in log-radius
const nb = 2 + Math.round(P.density * 6 + inten * 2);   // sub-bands per recursion level
const expo = 0.85 + P.energy * 0.4 + A.bass * 0.6 + inten * 0.2;
const scl = 0.35 + P.scale * 1.0;
