  const r = 0.5 + 0.5 * Math.cos(6.2831 * (m + hr));
  const gg = 0.5 + 0.5 * Math.cos(6.2831 * (m + hr + 0.33));
  const b = 0.5 + 0.5 * Math.cos(6.2831 * (m + hr + 0.67));
