      let band = 0.5 + 0.5 * Math.cos(6.2831 * bp);
      let shade = 0.32 + 0.68 * band;
      r0 = c[0] * shade * expo + 0.06;
      g0 = c[1] * shade * expo + 0.06;
      b0 = c[2] * shade * expo + 0.06;
    }
    const cf = Math.min(1, 0.05 + r * 14);               // focal sink: darken the inward-forever center
    r0 *= cf; g0 *= cf; b0 *= cf;
    const o = 4 * (j * BW + i);
    px[o]     = Math.max(0, Math.min(255, r0 * 255));
    px[o + 1] = Math.max(0, Math.min(255, g0 * 255));
    px[o + 2] = Math.max(0, Math.min(255, b0 * 255));
